const bus=(name,address)=>[wire('ESP32 3V3',`${name} VIN`,'3V3'),wire('Common GND',`${name} GND`,'GND'),wire('GPIO8 · J1-12',`${name} SDA`,'I2C SDA',`Shared bus; ${address}`),wire('GPIO9 · J1-15',`${name} SCL`,'I2C SCL','Use 3.3 V pull-ups; start at 100 kHz.')];
