export const getProfile=id=>profiles.find(p=>p.id===id)||profiles[0];
export function connections(profile){return profile.parts.flatMap(id=>parts[id].wires.map(row=>({component:id,...row})));}
export function bom(profile){const tally=new Map();for(const id of profile.parts)for(const [item,qty] of parts[id].bom)tally.set(item,(tally.get(item)||0)+qty);return [...tally].map(([item,quantity])=>({item,quantity}));}
export function pinAssignments(profile){const p=[['I2C_SDA',8],['I2C_SCL',9],['LED_DATA',4]];if(profile.parts.includes('pir'))p.push(['PIR_OUT',7]);if(profile.parts.includes('button'))p.push(['FOCUS_BUTTON',5]);if(profile.parts.includes('buzzer'))p.push(['BUZZER_GATE',6]);if(profile.parts.includes('mic'))p.push(['MIC_BCLK',15],['MIC_WS',16],['MIC_DATA',17]);if(profile.parts.includes('amp'))p.push(['AMP_BCLK',18],['AMP_WS',21],['AMP_DATA',47],['AMP_ENABLE',6]);return p;}
export function arduinoSketch(profile){return `/* ORBIT ${profile.name} — electrical bring-up scaffold\n * Board: ESP32-S3-DevKitC-1 v1.1 / WROOM-1 N8R8\n * Select ESP32S3 Dev Module in the Espressif Arduino core.\n * Enable USB CDC On Boot for the native USB port, or use USB-UART.\n * Disconnect the external 5V lead and high-current loads before USB programming.\n * This scans I2C and reads digital inputs; it is NOT complete application firmware.\n * No LED protocol, display renderer, sensor driver or audio pipeline is started.\n */\n#include <Arduino.h>\n#include <Wire.h>\n\n${pinAssignments(profile).map(([name,pin])=>`constexpr int ${name} = ${pin};`).join('\n')}\n\nvoid setup() {\n  Serial.begin(115200);\n  delay(1500);\n  pinMode(LED_DATA, OUTPUT); digitalWrite(LED_DATA, LOW);\n${profile.parts.includes('pir')?'  pinMode(PIR_OUT, INPUT);\n':''}${profile.parts.includes('button')?'  pinMode(FOCUS_BUTTON, INPUT_PULLUP);\n':''}${profile.parts.includes('buzzer')?'  pinMode(BUZZER_GATE, OUTPUT); digitalWrite(BUZZER_GATE, LOW);\n':''}${profile.parts.includes('amp')?'  pinMode(AMP_ENABLE, OUTPUT); digitalWrite(AMP_ENABLE, LOW); // keep muted\n':''}  Wire.begin(I2C_SDA, I2C_SCL, 100000);\n  Serial.println("Orbit ${profile.name}: I2C scan");\n  for (uint8_t address = 1; address < 127; ++address) {\n    Wire.beginTransmission(address);\n    if (Wire.endTransmission() == 0) Serial.printf("Found 0x%02X\\n", address);\n  }\n  Serial.println("Match addresses to the wiring table, then test one module at a time.");\n}\n\nvoid loop() {\n${profile.parts.includes('pir')?'  Serial.printf("Motion=%d\\n", digitalRead(PIR_OUT));\n':''}${profile.parts.includes('button')?'  Serial.printf("Button=%s\\n", digitalRead(FOCUS_BUTTON) == LOW ? "pressed" : "released");\n':''}  delay(500);\n}\n`;}
export function plan(profile){return {version:1,application:profile.name,board:'ESP32-S3-DevKitC-1 v1.1 N8R8',status:'Educational modular wiring plan; unbuilt and not ERC/DRC-validated. Not Gerber, CAD, or a manufacturing netlist.',power:'Single regulated 5V/2A supply in standalone mode; USB disconnected. 3.3V GPIO only.',assembly:profile.parts.map((id,index)=>({order:index+1,ref:parts[id].ref,name:parts[id].name,part:parts[id].spec,placement:parts[id].placement,instructions:parts[id].assembly,test:parts[id].check})),connections:connections(profile),billOfMaterials:bom(profile),gpio:pinAssignments(profile)};}
